package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamAppliedPracticalBank2 {
    private const val T = "ගායන ශිල්පය, ශ්‍රව්‍ය විද්‍යාව, ප්‍රායෝගික පරීක්ෂණ හා සෞන්දර්ය රසය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ශ්‍රව්‍ය විද්‍යාවට අනුව සංගීත ශබ්දයක ප්‍රධාන භෞතික ගුණාංග තුන කුමක්ද?", "තාරතාව (Pitch), ප්‍රබලතාව (Loudness) සහ නාද ගුණය (Timbre)", "වර්ණය, බර සහ උෂ්ණත්වය", "දිග, පළල සහ ඝනත්වය", "තාලය, පදය සහ රාගය පමණක්", "ඕනෑම සංගීත නාදයක තාරතාව, ප්‍රබලතාව හා නාද ගුණය යන ලක්ෂණ 3 පවතී."),
        q("ගායනයේදී හඬ පුහුණු කිරීම සඳහා භාවිත කරන 'ස - ස රි ස - ස රි ග රි ස' වැනි ස්වර අභ්‍යාස හඳුන්වන්නේ කෙසේද?", "අලංකාර හෙවත් පල්ටා (Alankar / Palta) අභ්‍යාස", "වන්නම් හා සැහැලි", "සම සහ ඛාලි", "තාලි සහ චෞගුන්", "ස්වර පෙළ නිවැරදිව උච්චාරණය හා ගායනය ප්‍රගුණ කිරීමට අලංකාර පුහුණු වීම ඉවහල් වේ."),
        q("නවක ගායකයෙකු 'අලංකාර' අභ්‍යාස පුහුණු වීමෙන් ලබාගන්නා ප්‍රධාන ප්‍රයෝජනය කුමක්ද?", "උගුරේ නම්‍යශීලී බව, ස්වර ස්ථාන දැනුම හා තාන හැකියාව දියුණු වීම", "තබ්ලාව සුසර කිරීමට හැකිවීම", "බටනළාව පිඹීමට ඉගෙන ගැනීම", "කවි මතක තබා ගැනීම පමණක්", "පල්ටා පුහුණුව මගින් කටහඬේ වේගවත් චලනය හා ස්වර නිවැරදිතාව ඉහළ යයි."),
        q("ගායනා කිරීමේදී මිනිස් හඬෙහි ස්වාභාවික 'මන්ද්‍ර, මධ්‍ය සහ තාර' යන සප්තක තුනට පිළිවෙළින් හඬ උපදින ශරීර ස්ථාන මොනවාද?", "උරස්, කණ්ඨ සහ ශීර්ෂ ප්‍රදේශ (හෘදය, උගුර, හිස)", "පාද, ඉණ සහ දණහිස්", "දෑත්, ඇඟිලි සහ උරහිස්", "බෙල්ල, කන සහ නළල පමණක්", "භාරතීය ග්‍රන්ථවල හෘදය (මන්ද්‍ර), කණ්ඨය (මධ්‍ය) හා මුර්ධ/හිස (තාර) ස්ථාන ලෙස දක්වයි."),
        q("සංගීත පන්තියේදී 'ආකාර' (Aakaar) පුහුණුව ලෙස හඳුන්වනු ලබන්නේ කුමක්ද?", "ස, රි, ග, ම නොකියා 'ආ' ශබ්දයෙන් ස්වර හා අලංකාර ගැයීම", "ඉංග්‍රීසි හෝඩිය ගායනය", "මුමුණමින් නාසිකව ගැයීම", "අත්පොළසන් දීම පමණක්", "සියලු ස්වර පිරිසිදු 'ආ' ශබ්දයෙන් ගැයීමෙන් විවෘත හඬ හා රාග රසය වැඩි වේ."),
        q("'සර්ගම්' (Sargam) ගායනය යනු කුමක්ද?", "ස, රි, ග, ම, ප, ධ, නි යන ස්වර නාම උච්චාරණය කරමින් ගැයීම", "වචන රහිතව 'හ්ම්' ශබ්දයෙන් ගැයීම", "කවි පද පමණක් කියවීම", "බෙර අක්ෂර කටින් කීම", "රාගයේ ස්වර සංයෝජනය හා තාල රටාව පෙන්වමින් ස්වර නම්වලින්ම ගැයීම සර්ගම් නම් වේ."),
        q("ප්‍රායෝගික පරීක්ෂණයේදී 'ලක්ෂණ ගීතයක්' (Lakshan Geet) ගායනා කිරීමේ අරමුණ කුමක්ද?", "එම රාගයේ වාදී, සංවාදී, ථාට හා ගායන වේලාව ගීතයෙන්ම විස්තර කිරීම", "හාස්‍යජනක කතාවක් කීම", "වේගවත් නර්තනයක් දැක්වීම", "බටහිර සංගීතය හඳුන්වා දීම", "රාග ලක්ෂණ මතක තබා ගැනීමට පහසු වන සේ රාගය තුළම ගැයෙන ගීත ලක්ෂණ ගීත වේ."),
        q("'බන්දිශ්' (Bandish) යනුවෙන් උත්තර භාරතීය ශාස්ත්‍රීය සංගීතයේ හඳුන්වනු ලබන්නේ කුමක්ද?", "නිශ්චිත රාගයකට හා තාලයකට බඳින ලද කාව්‍යමය ගීත රචනාව", "තාල රහිත ආලාප කොටස", "වේදිකාවේ පසුබිම් තිරය", "තබ්ලාවේ කොටසක්", "ස්ථායි හා අන්තරා සහිතව නියමිත තාලයකට ගැයෙන ශාස්ත්‍රීය ගීතය බන්දිශ් හෙවත් චීස් වේ."),
        q("ශාස්ත්‍රීය රාග වාදනයේදී (සිතාර්, බන්සූරි) බන්දිශ් වෙනුවට වාදනය කරන නිබන්ධ ස්වර රචනාව කුමක්ද?", "ගත් (Gat)", "ආලාප්", "පකඩ්", "මීන්ඩ්", "සිතාරය ආදී තත හා සුසිර භාණ්ඩවල තබ්ලාව සමඟ වයන තාලානුකූල රචනාව ගත් නම් වේ."),
        q("සිතාර් වාදනයේදී ප්‍රධාන ගත් වර්ග දෙක ලෙස ප්‍රචලිත වන්නේ මොනවාද?", "මසිත්ඛානි ගත් (විලම්බ) සහ රසාඛානි ගත් (මධ්‍ය/දෘත)", "ඛ්‍යාල් සහ ඨුම්රි", "ආතත සහ විතත", "සම සහ ඛාලි", "මසිත්ඛානි විලම්බ ලයෙන්ද, රසාඛානි දෘත ලයෙන්ද වයන සම්භාව්‍ය ගත් වර්ග දෙකයි."),
        q("ප්‍රායෝගික සංගීත විභාගයකදී 'රාගයක ඡායාව' ඉස්මතු කිරීමට මුලින්ම කරනු ලබන තාල රහිත ගායනය කුමක්ද?", "ආලාපය (Alap)", "දෘත තාන", "සර්ගම් තිහාය", "චෞගුන් ලය", "තබ්ලාව නොමැතිව හෝ තාලයකට බැඳී නොසිට රාගයේ ස්වර විහිදුවමින් සෙමින් ගයන කොටස ආලාපයයි."),
        q("ශාස්ත්‍රීය ගායනයක හෝ වාදනයක අවසානය හඟවමින් එකම ස්වර හෝ තාල ඛණ්ඩයක් තුන් වරක් වයා සම මත නවතාලීම කුමක්ද?", "තිහායි (Tihai)", "ආලාප්", "මීන්ඩ්", "විභාග", "තුන් වතාවක් සමානව ගයා හෝ වයා තාලයේ පළමු මාත්‍රාව වන සම මත කෙළවර කිරීම තිහායි වේ."),
        q("තාල පුහුණුවේදී 'තාලයේ වේගය මධ්‍යම ප්‍රමාණයට' පවත්වා ගෙන යන සාමාන්‍ය ලය කුමක්ද?", "මධ්‍ය ලය", "විලම්බ ලය", "දෘත ලය", "අති දෘත ලය", "විලම්බයට වඩා වේගවත් සහ දෘතයට වඩා මන්දගාමී වූ සාමාන්‍ය ගායන ලය මධ්‍ය ලයයි."),
        q("සංගීත ශිෂ්‍යයෙකු 'තනිව සරල ගීයක් ගැයීමේදී' (Solo Singing) මයික්‍රොෆෝනය භාවිත කළ යුත්තේ කෙසේද?", "මුඛයට සෙ.මී. 10-15ක් පමණ දුරින් හඬ සමබරව තබාගෙන", "තොල්වල තදින් ගාවාගෙන", "පිටුපස හරවාගෙන", "සෙලවෙමින් එහා මෙහා ගමන් කරමින්", "ස්ථාවර දුරක් තබා ගැනීමෙන් ශබ්ද පාලනය (Sound level) ඒකාකාරව පවත්වා ගත හැකිය."),
        q("චිත්‍රපට සංගීතයේදී 'පසුබිම් සංගීතය' (Background Score) මගින් සිදුවන ප්‍රධාන කාර්යය කුමක්ද?", "දර්ශනයේ භාවය, ආතතිය හෝ සතුට ප්‍රේක්ෂකයාට දැනවීම", "නළුවන්ගේ දෙබස් නෑසෙන සේ කිරීම", "චිත්‍රපටය අවසන් වූ බව කීම පමණක්", "කැමරාවේ දෝෂ වැසීම", "රූප රාමුවේ ඇති හැඟීම්බර අවස්ථා වඩාත් තීව්‍ර කිරීමට පසුබිම් සංගීතය ඉවහල් වේ."),
        q("ටෙලිනාට්‍ය හා ගුවන්විදුලි වැඩසටහන්වල 'තේමා ගීතය' (Theme Song) නිර්මාණය කිරීමේදී අවධානය යොමු කරන්නේ කුමකටද?", "කතාවේ සමස්ත අරමුණ හා සමාජ පසුබිම කෙටියෙන් ධ්වනිත කිරීමට", "ඕනෑම ජනප්‍රිය බටහිර ගීතයක් දැමීමට", "කතාවට කිසිසේත්ම අදාළ නැති තනුවක් ගැනීමට", "වාද්‍ය භාණ්ඩ එකක් පමණක් ගැනීමට", "තේමා ගීතය ප්‍රේක්ෂකයාට වැඩසටහනේ හරය හා මනෝභාවය ක්ෂණිකව සිහිගන්වයි."),
        q("වෙළඳ දැන්වීම් සංගීතයේ (Jingles) ප්‍රධානතම ලක්ෂණය කුමක්ද?", "කෙටි කාලයක් තුළ මතකයේ රැඳෙන ආකර්ෂණීය තනුවක් වීම", "විනාඩි 30ක විලම්බ රාග ආලාපයක් වීම", "තේරුම් ගැනීමට අපහසු සංස්කෘත ශ්ලෝක වීම", "කිසිදු රිද්මයක් නොමැති වීම", "තත්පර 15-30 වැනි කෙටි කාලයකදී පණිවිඩය පාරිභෝගික මතකයේ රැඳවීම ජින්ගල්වල අරමුණයි."),
        q("පාසල් සංගීත කාමරයේදී 'කණ්ඩායම් ගායනය' පුහුණු වන සිසුන් සැමවිටම සවන් දිය යුත්තේ කාටද?", "සමූහ නායකයාට සහ ආධාරක තාල-ශ්‍රැති වාද්‍යයන්ට", "තමන්ගේම හඬට පමණක්", "ශාලාවෙන් පිටත ශබ්දවලට", "කිසිවෙකුට සවන් නොදිය යුතුය", "අනෙක් සාමාජිකයන්ගේ හඬ හා ස්වර සමඟ ගැළපෙමින් ගැයීමට සක්‍රීය ශ්‍රවණය අත්‍යවශ්‍ය වේ."),
        q("සංගීත ශාලාවක ගෘහ නිර්මාණ ශිල්පයේදී (Acoustics Design) පැතලි සමාන්තර බිත්ති වෙනුවට අක්‍රමවත් පෘෂ්ඨ යොදන්නේ ඇයි?", "අනවශ්‍ය ශබ්ද පරාවර්තන හා දෝංකාර වැළැක්වීමට", "බිත්තිවල වර්ණය වෙනස් කිරීමට", "ශාලාවේ වාතාශ්‍රය නැති කිරීමට", "වැඩි පිරිසක් ඇතුළු කිරීමට", "සුමට බිත්ති මත ශබ්දය වැදී පරාවර්තනය වීමෙන් ශ්‍රවණ පැහැදිලි බව අඩුවීම වළකාලීමටය."),
        q("ඩිජිටල් සංගීත නිෂ්පාදනයේදී (Digital Audio Production) ශබ්දය පටිගත කිරීමට පෙර 'Click Track' (Metronome) භාවිත කරන්නේ ඇයි?", "සියලුම භාණ්ඩ හා ගායනා නිශ්චිත ස්ථාවර වේගයක (BPM) තැබීමට", "හඬ විකෘති කිරීමට", "සිතාරය සුසර කිරීමට", "ගීතයේ වචන මකා දැමීමට", "පටිගත කිරීමේදී එක් එක් ඛණ්ඩය නිවැරදි තාල වේගයට පෙළගැස්වීමට Click Track උදව් වේ."),
        q("ශබ්ද පටිගත කිරීමේදී 'මික්සින්' (Mixing) ක්‍රියාවලියෙන් අදහස් කරන්නේ කුමක්ද?", "සියලු ගායන හා වාද්‍ය ධාවන පථවල හඬ සමබර කර අලංකාර කිරීම", "වාද්‍ය භාණ්ඩ එකට ගැටගැසීම", "තැටි පෙට්ටිවල ඇසිරීම", "ගීත පද කලවම් කර ලිවීම", "පටිගත කළ හඬ, ඩ්‍රම්ස්, සිතාර් ආදියේ ශබ්ද මට්ටම් හා ගුණාත්මක බව සීරුමාරු කිරීම Mixing වේ."),
        q("O/L ප්‍රායෝගික පරීක්ෂණයේදී 'ස්වර පෙළක් හඳුනාගැනීමේ' (Swara Identification) ප්‍රශ්නයට සාර්ථකව පිළිතුරු දීමට සිසුවා දැනගත යුත්තේ කුමක්ද?", "ශුද්ධ හා විකෘති ස්වර 12හි ශ්‍රැති ස්ථාන අතර ඇති පරතරය", "රාග ගයන වේලාවන් පමණක්", "වාද්‍ය භාණ්ඩ නිපදවූ රට", "තබ්ලා ගට්ටා ගණන", "ෂඩ්ජය සිතේ තබාගෙන ගුරුවරයා වයන ස්වර ඊට සාපේක්ෂව කුමන ස්වරදැයි හඳුනාගත යුතුය."),
        q("ප්‍රායෝගික ගායනා පරීක්ෂණයකදී 'තාලය අතින් ගණන් ගන්නා අතරතුර ගීතය ගැයීම' පහසු වන්නේ කුමක් ප්‍රගුණ කළ විටද?", "තාලයේ සම හා ඛාලි ස්ථානවල පද යෙදෙන තැන් හොඳින් හඳුනාගත් විට", "දෑස් වසාගත් විට", "අත් දෙක සාක්කුවේ දමාගත් විට", "ඉතා වේගයෙන් හුස්ම ගත් විට", "අත්තාලය සමඟ ගීතයේ මුඛඩාව සම්බන්ධ වන තැන නිවැරදිව පුහුණු වීමෙන් වැරදීම් අඩු වේ."),
        q("ශ්‍රී ලංකාවේ 'ජන ගීයක්' ප්‍රායෝගික විභාගයට ඉදිරිපත් කිරීමේදී ගායනය සමඟ තාල සපයා ගැනීමට වඩාත් සුදුසු වන්නේ කුමක්ද?", "එම ජන ගීයට උචිත ගැටබෙර, යක්බෙර, උඩැක්කි හෝ අත්තාලම", "විදුලි ජෑස් ඩ්‍රම් සෙට් එක", "බටහිර ට්‍රම්පට් නළාව", "පයිප් ඕගනය", "සාම්ප්‍රදායික ජන ගීයේ ස්වභාවය නොනැසෙන දේශීය තාල භාණ්ඩ හෝ අත්තාලම යොදාගත යුතුය."),
        q("සංගීතයේදී 'ශ්‍රවණ විඩාව' (Ear Fatigue) ඇතිවීම වළක්වා ගැනීමට හෙඩ්ෆෝන් භාවිතයේදී කළ යුත්තේ කුමක්ද?", "අධික ශබ්ද මට්ටම්වලින් දිගු වේලාවක් නොඅසා මධ්‍යස්ථ ශබ්දයකින් ඇසීම", "උපරිම ශබ්දයෙන් පැය ගණන් ඇසීම", "එක් කනක් පමණක් වසා තැබීම", "වතුර තුළ දමා ඇසීම", "ඩෙසිබල් 85ට වැඩි ශබ්දය දිගු කල් ඇසීම කනේ ශ්‍රවණ සෛලවලට ස්ථිර හානි පමුණුවයි."),
        q("ශාස්ත්‍රීය රාගයක් ගැයීමේදී ගායකයා තම 'නියමිත ශ්‍රැතියට' වඩා ඉතා උස් හඬ පරිමාණයක් තෝරා ගතහොත් කුමක් සිදුවේද?", "තාර සප්තකයේ ස්වර ගැයීමේදී හඬ බිඳීම හෝ අපහසුතාව ඇති වේ", "ගායනය ඉතා පහසු වේ", "මන්ද්‍ර ස්වර වැඩිපුර ඇසේ", "තාලය ස්වයංක්‍රීයව වේගවත් වේ", "පරිමාණය වැරදි ලෙස තෝරා ගැනීමෙන් අන්තරා කොටසේ තාර ස්වර වෙහෙසකර වේ."),
        q("සරල ගීතයක හෝ නූර්ති ගීතයක 'සමූහ ගායන' අංගයකදී 'උච්ච හා මන්ද්‍ර' හඬවල් බෙදීමෙන් ලැබෙන ප්‍රතිඵලය කුමක්ද?", "හඬෙහි ගැඹුරු පිරිපුන් බව හා සංගීතමය පරිමාණය වැඩි වීම", "ගීතය කැත වී යාම", "ගායකයන් අතර ගැටුම් ඇතිවීම", "තාලය නැති වී යාම", "පිරිමි හා කාන්තා හඬ පරාසයන් නිසි ලෙස සංයෝජනය කිරීමෙන් ගීතය සමෘද්ධිමත් වේ."),
        q("ගායනයට පෙර සිසුන් 'හඬ උණුසුම් කිරීමේ' (Vocal Warm-up) අභ්‍යාස කිරීම වැදගත් වන්නේ ඇයි?", "ස්වර තන්තු ලිහිල් කර සම්පූර්ණ පරාසයේ ගැයීමට සූදානම් වීමට", "උගුරේ පේශි තද කර රළු හඬක් ගැනීමට", "පෙණහලුවල හුස්ම සම්පූර්ණයෙන් අවසන් කිරීමට", "ගායන කාලය අනවශ්‍ය ලෙස දිගු කර ගැනීමට", "ක්‍රීඩාවකට පෙර ශරීරය සූදානම් කරන්නා සේම හම් (Hum) හා ස්වර අභ්‍යාස මගින් හඬ සූදානම් කරයි."),
        q("රාගයක් පිළිබඳ Viva පරීක්ෂණයේදී 'ප්‍රකෘති ස්වර' යනු කුමක්දැයි ඇසුවහොත් නිවැරදි පිළිතුර කුමක්ද?", "සප්තකයේ තම නියමිත මූලික ස්ථානයේ පිහිටි ශුද්ධ ස්වර 7 බව", "සියලු කෝමල ස්වර පමණක් බව", "තීව්‍ර මධ්‍යමය පමණක් බව", "වර්ජිත ස්වර බව", "විකෘති නොවූ මූලික ශුද්ධ ස්වර හත ප්‍රකෘති ස්වර ලෙස හැඳින්වේ."),
        q("'ඒක ස්වර ගායනය' (Monotone) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "උස් පහළ යෑමකින් තොරව එකම ස්වරයක පමණක් රැඳී ගැයීම හෝ කීම", "සප්තක තුනේම ගැයීම", "රාග දෙකක් මිශ්‍ර කර ගැයීම", "වේගයෙන් තාන ගැයීම", "කිසිදු නාද විචලනයක් නැතිව එකම ස්වරයක රැඳීම නිසා ගායනය නීරස වේ."),
        q("සංගීතයේදී 'ස්වර පරිමාණය' (Scale / පටිපාටිය) යනු කුමක්ද?", "නිශ්චිත අනුපිළිවෙළකට අනුව පහළ සිට ඉහළට පෙළගැසුණු ස්වර මාලාවකි", "තාලයේ මාත්‍රා බෙදීමකි", "තබ්ලා බෝල් එකතුවකි", "වාද්‍ය භාණ්ඩයක බර මැනීමකි", "ස-රි-ග-ම-ප-ධ-නි-සං වැනි ක්‍රමවත්ව ඉහළ නගින හෝ පහළ බසින ස්වර පෙළ පරිමාණයයි."),
        q("ප්‍රායෝගික පරීක්ෂණයේදී 'භාව ගීතයක්' හෝ 'සරල ගීයක්' ඉදිරිපත් කිරීමේදී ගායකයා අත්හළ යුතු අඩුපාඩුවක් කුමක්ද?", "පද අමතක වීම, අවධානය බිඳීම හා ව්‍යාජ කෘත්‍රිම අභිනය", "පැහැදිලි උච්චාරණය", "නිවැරදි තාල රැකීම", "භාවාත්මක ඉදිරිපත් කිරීම", "ගීතයේ වචන හා තනුව පිළිබඳ පූර්ණ මතකය හා අව්‍යාජ හැඟීම් ප්‍රකාශනය අවශ්‍ය වේ."),
        q("සංගීතයේදී 'ස්වර සංගතිය' (Consonance) යනුවෙන් හඳුන්වනු ලබන්නේ කුමක්ද?", "ස්වර දෙකක් හෝ කිහිපයක් එකට හෝ පිළිවෙළින් ඇසෙන විට කනට මිහිරි එකඟතාවක් දැනීම", "ස්වර දෙකක් එකිනෙකට ගැටී කර්කශ වීම", "සම්පූර්ණ නිහැඬියාව පැවතීම", "තාලය කැඩී යෑම", "ෂඩ්ජය හා පංචමය (ස-ප) වැනි ස්වර අතර පවතින සුමිහිරි නාද එකඟතාව මීට උදාහරණයකි."),
        q("එකට වැයෙන ස්වර අතර කර්කශ හා නොගැළපෙන ස්වභාවය හඳුන්වනු ලබන්නේ කුමන නමින්ද?", "විසංවාදී බව (Dissonance)", "සංවාදී බව (Consonance)", "අනුනාදය (Resonance)", "පරිපූර්ණ ශ්‍රැතිය", "නිදසුනක් ලෙස ශුද්ධ රි සහ කෝමල රි එකවර වැයීමේදී විසංවාදී කර්කශ නාදයක් ඇති වේ."),
        q("වස්තුවක ස්වාභාවික කම්පන සංඛ්‍යාතයට සමාන වෙනත් ශබ්ද තරංගයක් වැදීමෙන් එය ඉබේම කම්පනය වීම කුමක්ද?", "අනුනාදය (Resonance)", "පරාවර්තනය (Reflection)", "වර්තනය (Refraction)", "විවර්තනය", "සිතාරයේ ප්‍රධාන තන්තුව වැයූ විට ඊට අනුරූපව යට ඇති තරබ් තන්තු නාද වන්නේ අනුනාදය නිසාය."),
        q("තම්බුරාවේ ලබු තුම්බාව මෙන්ම ගිටාරයේ හා වයලීනයේ හිස් ලී පෙට්ටිය මගින් සිදු කෙරෙන භෞතික කාර්යය කුමක්ද?", "තන්තු කම්පනය වීමෙන් උපදින කුඩා ශබ්දය අනුනාද කර විශාල කිරීම", "තන්තු තදින් බැඳ තැබීම පමණක්", "වාදකයාගේ අත රඳවා ගැනීම", "දහඩිය පිසදැමීම", "අනුනාද කුටීරය (Sound Box) ඇතුළත වායු කඳ කම්පනය වී ශබ්දයේ ප්‍රබලතාව වැඩි කරයි."),
        q("දෘශ්‍ය හා ශ්‍රව්‍ය මාධ්‍ය ඔස්සේ සංගීතය පටිගත කිරීමේදී ශබ්දයේ ගුණාත්මක බව මැනීමට 'Equalizer (EQ)' භාවිත කරන්නේ ඇයි?", "පහළ (Bass), මැද (Mid) සහ ඉහළ (Treble) සංඛ්‍යාත පරාස සමබර කිරීමට", "තාලයේ වේගය අඩු කිරීමට", "ගීතයේ වචන වෙනස් කිරීමට", "විදුලිය ඉතිරි කිරීමට", "EQ මගින් අනවශ්‍ය බේස් හෝ කර්කශ උස් සංඛ්‍යාත අඩු වැඩි කර පැහැදිලි හඬක් ලබාගනී."),
        q("ශ්‍රී ලංකාවේ පාසල් අතර පැවැත්වෙන 'සමස්ත ලංකා සංගීත තරඟාවලිය' වැනි අවස්ථාවලදී විනිශ්චය මණ්ඩලය වැඩි අවධානයක් යොමු කරන්නේ කුමකටද?", "ශ්‍රැති-ලය නිවැරදිතාව, කටහඬ/වාදන ශිල්පය හා සෞන්දර්ය භාවය", "තරඟකරුවන්ගේ ඇඳුමේ මිල ගණන්වලට පමණක්", "පසුබිම් සැරසිලිවල විශාලත්වයට", "පැමිණි ප්‍රේක්ෂක සංඛ්‍යාවට", "ශාස්ත්‍රීය හා ප්‍රාසාංගික නිර්ණායක අනුව ස්වර, තාල, උච්චාරණ හා නිර්මාණශීලීත්වය ඇගයේ."),
        q("රාගයක් ප්‍රායෝගිකව ඉදිරිපත් කිරීමේදී 'තාලයකට' නොබැඳී රාග ස්වර විහිදුවන 'නෝම්-තෝම්' (Nom-Tom) ආලාපය බහුලව යෙදෙන්නේ කවර ගායනයකද?", "ධ්‍රැපද් හා සිතාර් ජෝඩ්-ජාලා වාදනයේදී", "සරල ගීතවල", "කෝලම් නාට්‍යවල", "බයිලා ගීතවල", "අර්ථ රහිත 'නෝම්, තෝම්, තන, රී' වැනි අක්ෂර යොදා ධ්‍රැපද් ආලාපය ඉදිරිපත් කෙරේ."),
        q("ප්‍රායෝගික පරීක්ෂණයකදී කුඩා ගීතයක් හෝ ස්වර මාලාවක් 'කොළයක් බලා ගැනීමෙන්' (Sight Singing) තොරව කටපාඩමින් ගැයීම වැදගත් වන්නේ ඇයි?", "ප්‍රසාංගික නිදහස හා භාව ප්‍රකාශනය වඩා හොඳින් සිදුවන නිසා", "කොළ ඉරී යන නිසා", "ඇස් පෙනීම දුර්වල වන නිසා", "තාලය අමතක කිරීමට", "ස්වර හා පද මනසෙහි පිහිටා ඇති විට ආත්මවිශ්වාසයෙන් හා භාවාත්මකව ගායනා කළ හැකිය."),
        q("වේදිකාවේ සිටින ශිල්පීන්ට ප්‍රසංගයක් අවසානයේදී ප්‍රේක්ෂකයන් අත්පොළසන් දෙන විට ශිල්පීන් කළ යුතු විනීත ආචාරය කුමක්ද?", "සිනහමුසු මුහුණින් හිස නමා සභාවට ආචාර කිරීම", "වහාම පිටුපස හරවා දිව යෑම", "ප්‍රේක්ෂකයන්ට දොස් පැවරීම", "වාද්‍ය භාණ්ඩ බිම දමා යෑම", "රසික අගය කිරීමට ගෞරව දැක්වීම සෑම කලාකරුවෙකුගේම උසස් සංස්කෘතික විනයයි."),
        q("කුඩා දරුවන්ට සංගීතය හඳුන්වා දීමේදී 'ළමා ගීත' සඳහා සුදුසුම ස්වර පරාසය කුමක්ද?", "මධ්‍ය සප්තකයේ පහසු ස්වර (ස සිට තාර ස හෝ රි දක්වා)", "අති මන්ද්‍ර සප්තකයේ ස්වර", "සප්තක තුනහමාරක පරාසය", "අති තාර සප්තකයේ පමණක්", "දරුවන්ගේ කටහඬට පීඩනයක් නොවන පරිදි සීමිත සරල ස්වර පරාසයක ළමා ගී සකස් විය යුතුය."),
        q("සිංහල ජන ගීයේ සහ කර්ණාටක/හින්දුස්ථානි සංගීතයේ දැකිය හැකි පොදු සෞන්දර්ය ලක්ෂණය කුමක්ද?", "සොබාදහම, භක්තිය හා මානව හැඟීම් නාදයෙන් ප්‍රකාශ කිරීම", "සියල්ල විදුලි යන්ත්‍රවලින් පමණක් වැයීම", "තාලයක් කිසිසේත්ම නොතිබීම", "එකම වචනයක් පමණක් කීම", "ලොව කවර සංගීත සම්ප්‍රදායක වුවද අරමුණ මිනිස් ජීවිතයේ අභ්‍යන්තර රසභාව ප්‍රකාශ කිරීමයි."),
        q("සංගීත නිර්මාණකරණයේදී 'තාල භේදය' (Poly-rhythm හෝ තාල මාරුව) යොදාගැනීමෙන් ගීතයකට හෝ නාට්‍යයකට ලැබෙන්නේ කුමක්ද?", "විවිධත්වය, නව ජවය සහ නාට්‍යමය හැඟීම් වෙනස", "ශ්‍රාවකයාට නින්ද යෑම", "තාලය සම්පූර්ණයෙන් අවලංගු වීම", "භාණ්ඩ සියල්ල නිහඬ වීම", "ගීතයේ අන්තරා කොටසේදී හෝ නාට්‍යමය අවස්ථාවේදී තාලය වෙනස් කිරීමෙන් නැවුම් බවක් ඇති වේ."),
        q("සිංහල ගීත කලාවේ 'විරෝධාකල්ප ගීත' (Protest Songs) මගින් සමාජයට ඉටු කරන ප්‍රධාන මෙහෙය කුමක්ද?", "සමාජ අසාධාරණය විවේචනය කර මානව හිතවාදී චින්තනය අවදි කිරීම", "හුදෙක් විනෝදය හා නැටුම පමණක් සැපයීම", "රජුට ප්‍රශස්ති ගැයීම පමණක්", "කිසිදු අර්ථයක් නොමැති වචන ගැයීම", "සංගීතය සමාජ ප්‍රගමනය හා මානව අයිතීන් වෙනුවෙන් හඬ නඟන මාධ්‍යයක් බව ඉන් පෙනේ."),
        q("ප්‍රායෝගික පරීක්ෂණයකදී වයලීනය හෝ සිතාරය වයන ශිෂ්‍යයෙකු 'සමබර හඬක්' ලබාගැනීමට කුමක් කළ යුතුද?", "ගජයේ පීඩනය හා වේගය මධ්‍යස්ථව හා ඒකාකාරව පවත්වා ගැනීම", "තන්තු කැඩෙන තරමට තදින් ගජය ඇදීම", "එක් කෙළවරකින් පමණක් තන්තුව ස්පර්ශ කිරීම", "තන්තු බුරුල් කර වැයීම", "සුමට හා පැහැදිලි වයලීන නාදයකට නිවැරදි Bow Control හෙවත් ගජ පාලනය අත්‍යවශ්‍ය වේ."),
        q("සිතාර් වාදනයේදී 'තෝඩා' (Toda) සහ 'ටාන්' (Taan) යනුවෙන් හඳුන්වනු ලබන්නේ මොනවාද?", "ගත් වාදනයට අදාළ වේගවත් ස්වර රටා සහ කෙටි අලංකාර විස්තාර", "සිතාරයේ පහළ ලබු කබල", "දකුණු අතේ මිස්රාබය", "තන්තු ඔතන ලී කූර", "ගත් රචනය අවසන් වූ පසු රාගයේ ආකෘතිය තුළ විවිධ වේගවත් ස්වර ඛණ්ඩ වැයීම තෝඩා වේ."),
        q("තබ්ලා ඒකල වාදනයකදී (Tabla Solo) ආරම්භයේදී හා අවසානයේදී ඉදිරිපත් කරන ප්‍රධාන අංග මොනවාද?", "පේෂ්කාර්, කායිදා, රේලා, ගත්, ටුක්ඩා සහ චක්‍රදාර්", "ආරෝහණ සහ අවරෝහණ පමණක්", "ස-ප-ස තම්බුරා තන්තු", "නූර්ති සර්පිනා තනු", "තබ්ලා ඒකල වාදනයේ පේෂ්කාර් සිට වේගවත් රේලා හා චක්‍රදාර් දක්වා ක්‍රමවත් පිළිවෙළක් ඇත."),
        q("තබ්ලාවේ 'කායිදා' (Kayda) යනු කුමක්ද?", "පල්ටා හා තිහායි මගින් විස්තාරය කරන නියමිත බෝල් වාදන නීතියකි", "තාලය සම්පූර්ණයෙන් අත්හැර නිදහසේ වයන කොටසකි", "බායා කොටස සෑදීමට භාවිත කරන ලෝහ බඳයි", "දායා මුහුණත මැද ආලේප කරන කළු සියාහි මිශ්‍රණයයි", "කායිදා යන වචනයේ අර්ථය 'නීතිය' යන්න වන අතර ඉන් අලුත් ප්‍රස්තාර නිපදවයි."),
        q("තබ්ලා වාදනයේදී 'ටුක්ඩා' (Tukda) හා 'පරන්' (Paran) අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "පරන් යනු පඛාවජ් ශෛලියේ බර අක්ෂර සහිත කොටස් වීම", "ටුක්ඩා යනු බන්සූරි වාදනයක් වීම", "පරන් කඩිප්පුවෙන් වැයීම", "දෙකම ගායනා කවි වීම", "පඛාවජ් වාදනයෙන් ආ විශාල ගාම්භීර බෝල් සහිත රචනා පරන් ලෙස හැඳින්වේ."),
        q("තබ්ලාවේ වයන 'නග්මා' (Nagma / ලහරා) යනුවෙන් හඳුන්වනු ලබන්නේ කුමක්ද?", "තබ්ලා ඒකල වාදනයේදී හාමෝනියම් හෝ සාරංගියෙන් නොකඩවා වයන තාලාවර්තන තනුව", "ගායකයා කියන විහිළු කවිය", "තබ්ලා මිටියේ නම", "බෙරයේ ආධාරක වළල්ල", "තබ්ලා වාදකයාට ලය හා සම පවත්වා ගැනීමට නොකඩවා ලහරා (Nagma) වයනු ලැබේ."),
        q("සංගීතයේ 'ප්‍රාථමික සංගීත කුසලතා' අතරින් 'ලය බද්ධ බව' (Sense of Rhythm) වර්ධනය කර ගැනීමට ඇති හොඳම ක්‍රමය කුමක්ද?", "සරල තාලයකට අත්පොළසන් ගසමින් පියවර තැබීම හා ගණන් කිරීම", "තාලය ගැන නොසිතා පොත් කියවීම", "හිස පහළට නමා නිදාගැනීම", "තනි ස්වරයක් පමණක් ගැයීම", "ශාරීරික චලන හා අත්තාලය සමඟ නිතිපතා පුහුණු වීමෙන් රිද්ම සංවේදනය මුවහත් වේ."),
        q("ගායනය හා වාදනය අතර පවතින භාරතීය 'ගායකී අංග්' (Gayaki Ang) යනු කුමක්ද?", "වාද්‍ය භාණ්ඩයකින් මිනිස් කටහඬේ ගායන භාව හා සියුම් මීන්ඩ් අනුකරණය කිරීම", "ගායකයා බෙර ගැසීම", "භාණ්ඩයෙන් තාල පද පමණක් ගැසීම", "ගායනා නතර කර නැටීම", "වයලීනය හා සිතාරය ගායනය මෙන් හැඟීම්බරව වැයීම ගායකී අංග් නම් වේ."),
        q("වාද්‍ය භාණ්ඩ වාදනයේදී 'තන්ත්‍රකාරී අංග්' (Tantrakari Ang) යනු කුමක්ද?", "මිස්රාබ් පහර, ජාලා හා තෝඩා සහිත තන්තු වාදන ශෛලිය", "ගායකයෙකු ඉතා උස් හඬින් ආලාප ගැයීමේ ශෛලිය", "බන්සූරි හා ෂෙහෙනායි වැනි සුසිර භාණ්ඩ පිඹීම", "තාලම්පට හා ඝන භාණ්ඩ එකට ගසා වාදනය කිරීම", "සිතාරය හා සරෝද් වැනි භාණ්ඩවල ස්වභාවික තන්තු තාක්ෂණය ඉස්මතු කර වැයීම මීට අයත්ය."),
        q("ප්‍රායෝගික විභාගයකදී 'තාල නාමය' පමණක් නොව 'ජාති' (Jati) පිළිබඳවද විමසුවහොත් කර්ණාටක තාල ජාති ගණන කීයද?", "ජාති 5 කි", "ජාති 3 කි", "ජාති 2 කි", "ජාති 12 කි", "මාත්‍රා 3, 4, 5, 7, 9 අනුව තිශ්‍ර, චතුරශ්‍ර, ඛණ්ඩ, මිශ්‍ර, සංකීර්ණ යන පංච ජාති පවතී."),
        q("සංගීතයේදී 'ප්‍රස්තාර' (Prastar / Permutation) කිරීම යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "දී ඇති ස්වර හෝ බෝල් කිහිපයක් විවිධ අනුපිළිවෙළට සකසා නව රටා නිර්මාණය කිරීම", "විශාල තීන්ත පුවරුවක් ඇඳීම", "වාද්‍ය භාණ්ඩය අලුත්වැඩියා කිරීම", "පොතක් පිටපත් කිරීම", "මෙරු හා ඛණ්ඩමේරු ක්‍රමවලින් ස්වර සංයෝජන ගණිතමයව වෙනස් කිරීම ප්‍රස්තාර වේ."),
        q("ගායනයේදී 'අභ්‍යාසයේ නියැළීම' (Riyaz) සඳහා වඩාත්ම සුදුසු පරිසරය හා මානසික තත්ත්වය කුමක්ද?", "නිහඬ, සන්සුන්, හොඳින් වාතාශ්‍රය ඇති පරිසරයක ඒකාග්‍ර සිතකින් පුහුණු වීම", "අධික ඝෝෂාකාරී වෙළඳපොළක් මැද", "නිදිමත හා වෙහෙසකර අවස්ථාවක", "වේගයෙන් ඇවිදිමින්", "ඒකාග්‍රතාවයෙන් හා නිවැරදිව ශ්‍රැති ඇසෙන නිහඬ පරිසරයක රියාස් කිරීම ඉතා ඵලදායී වේ."),
        q("සංගීත ශිල්පියෙකු ප්‍රසංග වේදිකාවකට යාමට පෙර සූදානම් වීමේදී වැදගත් නොවන දේ කුමක්ද?", "අනෙක් ශිල්පීන්ගේ භාණ්ඩ සැඟවීම", "තම භාණ්ඩය සුසර කර තැබීම", "පිළිවෙළකින් යුත් ප්‍රසංග ඇඳුමින් සැරසීම", "ගායන හා වාදන අනුපිළිවෙළ පරීක්ෂා කිරීම", "සංගීත කලාව තුළ සැමවිටම සහෝදරත්වය, විනය හා පූර්ව සූදානම අගය කෙරේ."),
        q("සරල ගීයක හෝ සම්භාව්‍ය ගීයක 'කටහඬ හා සංගීත භාණ්ඩ අතර සංවාදය' හඳුන්වන්නේ කෙසේද?", "සවල් - ජවාබ් රටාව", "බේසුර් වීම", "තාල භංග වීම", "විභාග රේඛාව", "ගායකයා ගැයූ ඛණ්ඩයට සිතාර් හෝ තබ්ලා වාදකයා පිළිතුරු ලෙස අනුරූප ඛණ්ඩ වැයීම සවල්-ජවාබ් වේ."),
        q("O/L සිසුවෙකු පෙරදිග සංගීත ප්‍රශ්න පත්‍රයේ රචනා හා ස්වර ලිපි කොටසට පිළිතුරු ලිවීමේදී වැඩි අවධානයක් දිය යුත්තේ කුමකටද?", "විකෘති ස්වර සංකේත, මන්ද්‍ර-තාර තිත් සහ තාල ලකුණු නිවැරදිව යෙදීමට", "අකුරු විශාලව ලිවීමට පමණක්", "පෑන් වර්ණ පහක් භාවිත කිරීමට", "චිත්‍ර ඇඳීමට", "ස්වර ලිපියේ කුඩා ඉරක් හෝ තිතක් වැරදුණහොත් සම්පූර්ණ ස්වරය හා සප්තකය වෙනස් වේ."),
        q("සංගීත ශාස්ත්‍රයේ 'ගුරු වන්දනාව' හා 'සරස්වතී වන්දනාව' මගින් ශිෂ්‍යයා තුළ ඇති කරන්නේ කුමන ආකල්පයක්ද?", "කලාව කෙරෙහි ගෞරවය, නිහතමානී බව හා විනය", "අහංකාරකම", "කලාව අවතක්සේරු කිරීම", "විභාග බිය", "ගුරුවරුන්ට හා විද්‍යාවට ගරු කරමින් නිහතමානීව ශිල්ප හැදෑරීමේ උතුම් ගුණය ඉන් රැකේ."),
        q("රාගයක් පිළිබඳ විස්තරයක් ලිවීමේදී සම්මත 'රාග පරිචය' (Raga Description) තුළ ඇතුළත් වන මූලික කරුණු පෙළ කුමක්ද?", "ථාටය, ආරෝහණ/අවරෝහණ, ජාතිය, වාදී-සංවාදී, වර්ජිත ස්වර හා ගායන වේලාව", "ගායකයාගේ වයස, ගම හා උපන් දිනය", "තබ්ලාවේ බර හා මිල", "රඟහලේ ආසන ගණන", "නිල O/L රාග විස්තරයක මෙම සියලු ශාස්ත්‍රීය අංග පිළිවෙළින් සඳහන් කළ යුතුය."),
        q("ශ්‍රව්‍ය විද්‍යාවේදී 'මනුෂ්‍ය කනට අහිතකර' ඉතා ඉහළ ශබ්ද තීව්‍රතා මට්ටමක් ලෙස සැලකෙන්නේ කවර සීමාව ඉක්මවූ විටද?", "ඩෙසිබල් 85 - 90 dB ඉක්මවා දිගු වේලාවක් ඇසීම", "ඩෙසිබල් 20 dB මට්ටම", "ඩෙසිබල් 40 dB මට්ටම", "ඩෙසිබල් 10 dB මට්ටම", "වැඩි dB මට්ටමේ ඝෝෂාව කනේ ස්නායු දුර්වල කර ශ්‍රවණාබාධ ඇති කරයි."),
        q("ගුවන්විදුලිය හරහා සංගීතය ශ්‍රවණය කිරීම සහ සජීවී ප්‍රසංගයක් නැරඹීම අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "සජීවී ප්‍රසංගයේදී කලාකරුවාගේ අභිනය හා සෘජු ප්‍රේක්ෂක සබඳතාවද අත්විඳීමට ලැබීම", "ගුවන්විදුලියේ ගීත නොඇසීම", "සජීවී ප්‍රසංගවල වාද්‍ය භාණ්ඩ නොමැති වීම", "ගුවන්විදුලියේ තාලය නැති වීම", "සජීවී වේදිකාවේදී දෘශ්‍ය හා ශ්‍රව්‍ය රසය එක්වී ක්ෂණික ජීවමාන අත්දැකීමක් ලැබේ."),
        q("දේශීය හා භාරතීය සංගීතය පිළිබඳව සිසුවෙකු සතු විය යුතු 'සමතුලිත රසිකත්වය' යනු කුමක්ද?", "විවිධ සංගීත ශෛලීන්හි හරය හඳුනාගෙන උසස් නිර්මාණ රසවිඳීමේ හැකියාව", "එක් ගීතයක් පමණක් ජීවිත කාලයටම ඇසීම", "ශාස්ත්‍රීය සංගීතය හෙළා දැකීම", "ජන සංගීතය අමතක කිරීම", "ශාස්ත්‍රීය, ජන, නාට්‍ය හා උසස් නව සංගීත නිර්මාණ සියල්ල විචාරශීලීව අගය කළ යුතුය."),
        q("සංගීත ශිල්පියෙකු තම වෘත්තියේදී 'නිර්මාණාත්මකව' කටයුතු කිරීම සඳහා වැඩිදියුණු කරගත යුතු කුසලතා මොනවාද?", "සවන්දීම, ශාස්ත්‍රීය න්‍යාය, ප්‍රායෝගික අභ්‍යාසය හා සාහිත්‍ය දැනුම", "හුදෙක් ප්‍රචාරණය පමණක්", "කිසිදු පුහුණුවක් නොමැතිව සිටීම", "අනෙක් ශිල්පීන් අනුකරණය කිරීම පමණක්", "ගැඹුරු අධ්‍යයනය හා නිතිපතා අභ්‍යාසය තුළින් පමණක් උසස් නිර්මාණකරුවෙකු බිහිවේ."),
        q("පෙරදිග සංගීතයේ 'රස නිෂ්පත්තිය' පිළිබඳව භරතමුනිගේ රස සූත්‍රයෙන් පෙන්වා දෙන කරුණ කුමක්ද?", "විභාව, අනුභාව හා ව්‍යභිචාරී භාව සංයෝගයෙන් රසය උපදින බව", "වාද්‍ය භාණ්ඩ මිල අධික විය යුතු බව", "තාලය සැමවිටම වේගවත් විය යුතු බව", "ස්වර 12ම එක් රාගයක තිබිය යුතු බව", "'විභාවානුභාව ව්‍යභිචාරී සංයෝගාත් රස නිෂ්පත්ති' යනුවෙන් නාට්‍ය ශාස්ත්‍රයේ දැක්වේ."),
        q("වේදිකා නාට්‍යයක හෝ ගීතයක 'සමබර හඬ පාලනය' (Voice Modulation) යන්නෙන් කුමක් කෙරේද?", "හැඟීම් අනුව හඬ මෘදු කිරීම, තීව්‍ර කිරීම හා විරාම තැබීම", "එක දිගටම එකම ශබ්දයෙන් කෑගැසීම", "කටහඬ සඟවා ගැනීම", "මයික්‍රොෆෝනය ක්‍රියා විරහිත කිරීම", "හඬෙහි උස් පහළ යෑම් හා තීව්‍රතා වෙනස් කිරීමෙන් ගායනය සජීවී හා ආකර්ෂණීය වේ."),
        q("ශ්‍රවණ විභාගයේදී 'තාල හඳුනාගැනීම' සඳහා ශිෂ්‍යයෙකු භාවිත කළ හැකි පහසුම උපක්‍රමය කුමක්ද?", "බෙර වාදනයේ අවධාරණය (සම) හා මාත්‍රා චක්‍රයේ බෙදීම මනසින් ගණන් කිරීම", "ගීතයේ වචන පමණක් ලියා ගැනීම", "දෑස් වසා නෑසී සිටීම", "අනුමානයෙන් අංකයක් ලිවීම", "සම සිට ඊළඟ සම දක්වා ඇති මාත්‍රා 3, 4, 6, 7, 8, 10, 12 හෝ 16 ගණන් කර තාලය හඳුනාගනී."),
        q("රාගයක් වයන හෝ ගයන අතරතුර 'ස්ථිර පදනම' ලෙස පවතින තම්බුරාව හදිසියේ නතර වුවහොත් ඇතිවිය හැකි බලපෑම කුමක්ද?", "ගායකයාගේ ශ්‍රැති ස්ථානය (Sa) පැටලීමට හෝ වෙනස් වීමට ඉඩ තිබීම", "තාලය වේගවත් වීම", "සියලුම දෙනාට හොඳින් ගැයීමට පහසු වීම", "ගීතයේ පද අමතක වීම", "තම්බුරාව ශාස්ත්‍රීය ගායනයට නිවැරදි ස්වර මාලිමාවක් මෙන් මග පෙන්වයි."),
        q("සිංහල සංගීතයේ 'රසික විචාරය' යනු කුමක්ද?", "සංගීත නිර්මාණයක ගුණාත්මක අංග හා අඩුපාඩු තාර්කිකව හා සෞන්දර්යාත්මකව විශ්ලේෂණය කිරීම", "නිර්මාණකරුවාට පෞද්ගලිකව බැණ වැදීම", "සියලු නව නිර්මාණ ප්‍රතික්ෂේප කිරීම", "වචන ගණන ගණන් කිරීම පමණක්", "නිර්මාණයක තාක්ෂණික හා කලාත්මක අගය මධ්‍යස්ථව පැහැදිලි කිරීම යහපත් විචාරයයි."),
        q("සංගීත විෂය පිළිබඳව G.C.E. O/L අධ්‍යයනය අවසන් කරන සිසුවෙකු සතුවිය යුතු මූලික පරිපූර්ණත්වය කුමක්ද?", "න්‍යාය, ප්‍රායෝගික ශිල්පය, දේශීය උරුමය හා සෞන්දර්ය රසවින්දනය යන සියල්ල සමබරව ලැබීම", "පොතේ ඇති පිටු ගණන මතක තබා ගැනීම පමණක්", "විභාගයෙන් පසු සංගීතය අමතක කිරීම", "තනි භාණ්ඩයක් පමණක් අලෙවි කිරීම", "දැනුම, කුසලතා හා ආකල්ප යන ත්‍රිවිධ අරමුණු සපුරා ගැනීම O/L සංගීත විෂයේ මූලික ඉලක්කයයි."),
        q("දේශීය නාට්‍ය, ජන ගී, ශාස්ත්‍රීය රාග සහ තාල පද්ධති එකම විෂය මාලාවක් තුළ ඉගැන්වීමෙන් සිසුවාට ලැබෙන වාසිය කුමක්ද?", "පුළුල් සංගීත ලෝක දැක්මක් හා නිර්මාණශීලී පරිකල්පනයක් ඇතිවීම", "විෂය බර වැඩි වී ව්‍යාකූල වීම පමණක්", "තනි ක්‍රමයක් පමණක් දැනගැනීම", "කිසිදු ප්‍රායෝගික දැනුමක් නොලැබීම", "බහුවිධ සංගීත සම්ප්‍රදායන් හඳුනාගැනීමෙන් වඩාත් දක්ෂ සංගීතඥයෙකු හා රසිකයෙකු බිහිවේ."),
        q("සංගීත ප්‍රසංගයකදී 'අවසන් මංගල ගීතය' හෝ අවසන් තිහායිය මගින් ප්‍රේක්ෂකයාට දැනෙන්නේ කුමක්ද?", "ප්‍රසංගයේ පරිපූර්ණ සමාප්තිය සහ සෞන්දර්යාත්මක තෘප්තිය", "තවදුරටත් ප්‍රසංගය පැවැත්වෙන බව", "වාද්‍ය භාණ්ඩ කැඩී ගිය බව", "වැරදීමක් සිදුවූ බව", "සුබදායක හා පිළිවෙළකින් යුත් සමාප්තියක් මගින් ප්‍රේක්ෂක මනසට සැනසිලිදායක නිමාවක් ලැබේ."),
        q("ගායනයට පෙර 'ස්වර පුහුණුව' (Vocal Warm-up) සිදු කිරීමෙන් ගායකයාට ලැබෙන සෞඛ්‍යමය හා කලාත්මක වාසිය කුමක්ද?", "ස්වර තන්ත්‍ර මෘදුව සැකසී ඉහළ හා පහළ ස්වර පැහැදිලිව ගැයීමට හැකි වීම", "කටහඬ සම්පූර්ණයෙන් වියළී යාම", "තාලයේ මාත්‍රා වෙනස් වීම", "ශ්වසන වේගය අවුල් වීම", "මන්ද්‍ර ස ස්වරයේ හම්මිං හා ආකාර අභ්‍යාස උගුරේ මාංශ පේශි සූදානම් කරයි."),
        q("ගායකයෙකු ගීතයක් ගයන අතරතුර නිවැරදි තැනින් 'හුස්ම ගැනීම' (Breath Control) කළ යුත්තේ කවදාද?", "ගීතයේ අර්ථය හා ස්වර ඛණ්ඩය අවසන් වන ස්වාභාවික විරාමයේදී", "වචනයක් මැදදී නවතා හදිසියේ", "තාලයේ සම ස්ථානය මගහැර", "පළමු ස්වරය ආරම්භයේම නතර කර", "වාක්‍ය අර්ථය නොකැඩෙන පරිදි ප්‍රාශ්වාස පාලනය කිරීම උසස් ගායන ලක්ෂණයකි."),
        q("ප්‍රායෝගික පරීක්ෂණයකදී සිසුවෙකු සිතාරය හෝ වයලීනය අල්ලාගෙන සිටින 'ඉරියව්ව' (Posture) නිවැරදි විය යුත්තේ ඇයි?", "අතට අපහසුවකින් තොරව නිදහසේ ඇඟිලි හැසිරවීමට සහ නිවැරදි ශබ්දය ගැනීමට", "ප්‍රේක්ෂකයාට බිය ගැන්වීමට", "භාණ්ඩය බිම තැබීම පහසු කිරීමට", "ඇඳුම පිරිසිදුව තබා ගැනීමට පමණක්", "නිවැරදි වාඩිවීමේ ඉරියව්ව කල් පවතින පුහුණුවටත් මිහිරි වාදනයටත් පදනම වේ."),
        q("සමූහ ගායන කණ්ඩායමක (Choir) සාමාජිකයන් සියලු දෙනාම අනිවාර්යයෙන්ම රැකගත යුතු ප්‍රධාන ගුණාංගය කුමක්ද?", "එකම ශ්‍රැතිය, එකම ලය සහ සමාන ශබ්ද සමබරතාව", "එක් එක් අය තමන් කැමති ස්වරයකින් ගැයීම", "අනෙක් අයට වඩා හයියෙන් කෑගැසීම", "වචන වෙනස් කරමින් ගැයීම", "සමූහ ගායනයේ සාර්ථකත්වය රඳා පවතින්නේ ඒකාබද්ධ හඬ මිශ්‍රණය මතය."),
        q("ශ්‍රවණ විභාගයකදී දෙනු ලබන කෙටි ස්වර පෙළක් අසා එය හඳුනා ගැනීමේදී මුලින්ම මනසේ රඳවා ගත යුතු ස්වරය කුමක්ද?", "ආධාරක ෂඩ්ජය (ස)", "තීව්‍ර මධ්‍යමය (ම්)", "තාර නිෂාදය (නිඃ)", "මන්ද්‍ර රිෂභය (රි̣)", "සියලු ස්වර ස්ථාන මැන ගනු ලබන්නේ මූලික ෂඩ්ජයට සාපේක්ෂව බැවිනි."),
        q("පෙරදිග සංගීතයේ 'රස නවය' අතුරින් වීර සංග්‍රාම හා දේශාභිමානී ගීත තුළින් ප්‍රධාන වශයෙන් උපදවන රසය කුමක්ද?", "වීර රසය", "කරුණා රසය", "භයානක රසය", "බීභත්ස රසය", "ධෛර්යය, ශක්තිය හා අභිමානය දනවන ගීත තුළ උත්සාහ ස්ථායි භාවයෙන් වීර රසය ජනිත වේ."),
        q("ගීතයක වේගය අඩු කිරීම හෝ මෘදු කිරීම මගින් ශෝකජනක සිදුවීමක් විස්තර කරන විට මතුවන රසය කුමක්ද?", "කරුණා රසය", "හාස්‍ය රසය", "රෞද්‍ර රසය", "අද්භූත රසය", "ශෝක ස්ථායි භාවය පදනම් කරගෙන දුක හා දයාව උපදවන විට කරුණා රසය ප්‍රකාශ වේ."),
        q("පෙරදිග සංගීත ශාස්ත්‍රයේ 'ශාන්ත රසය' මතු කිරීමට වඩාත් උචිත ගායන ස්වභාවය කවරේද?", "විලම්බිත ලයෙන් සුමට හා සන්සුන් ස්වර චලන යෙදීම", "අති වේගවත් රෞද්‍ර තාන් හා බෙර පහර යෙදීම", "උස් හඬින් කෑගසමින් ගැයීම", "විකෘති තාල මාරු කිරීම", "භක්ති හා භාවනාමය ගීතවලදී මෘදු ස්වර සංයෝජනයෙන් ශාන්ත රසය උපදී."),
        q("වර්තමානයේ ශ්‍රී ලංකාවේ දේශීය හා පෙරදිග සංගීතය සුරැකීමට හා ව්‍යාප්ත කිරීමට ප්‍රධාන වශයෙන් දායක වන රාජ්‍ය විශ්වවිද්‍යාලය කුමක්ද?", "සෞන්දර්ය කලා විශ්වවිද්‍යාලය", "මොරටුව ඉංජිනේරු ආයතනය", "වෛද්‍ය පර්යේෂණායතනය", "කෘෂිකර්ම විද්‍යාලය", "හේවුඩ් කලායතනයෙන් පෝෂණය වූ සෞන්දර්ය කලා විශ්වවිද්‍යාලය මෙරට ප්‍රමුඛ කලා කේන්ද්‍රයයි."),
        q("ගීත රචකයෙකු, සංගීත නිර්මාපකයෙකු සහ ගායකයෙකු අතර මනා සම්බන්ධතාවක් තිබීම වැදගත් වන්නේ ඇයි?", "පදමාලාවේ අර්ථය, තනුව සහ ගායන භාවය එකට ගැළපී උසස් ගීතයක් බිහිවීමට", "ගීතයේ කාලය විනාඩි විස්සක් කිරීමට", "එකම පද පේළිය නැවත නැවත මුද්‍රණය කිරීමට", "වාද්‍ය භාණ්ඩ සංඛ්‍යාව එකකට සීමා කිරීමට", "පද, තනුව හා හඬ ඒකාබද්ධ වූ විට පමණක් ශ්‍රාවක හදවත් දිනාගන්නා සාර්ථක ගීයක් බිහි වේ."),
        q("ශබ්දාගාරයක ගීතයක් පටිගත කිරීමේදී පසුබිම් අනවශ්‍ය ශබ්ද වැළැක්වීම සඳහා බිත්තිවලට යොදන විශේෂ ක්‍රමය කුමක්ද?", "ධ්වනි පාලන ආවරණ (Acoustic Soundproofing)", "වීදුරු ජනේල සියල්ල විවෘත කර තැබීම", "ටකරන් තහඩු සවි කිරීම", "මයික්‍රොෆෝන බිම තැබීම", "ශබ්ද පරාවර්තනය හා බාහිර ඝෝෂා අවම කිරීමට මෘදු පෙන හා ධ්වනි පුවරු භාවිත කෙරේ."),
        q("මයික්‍රොෆෝනයක් ඉදිරියේ ගායනා කරන විට පැහැදිලි හා දෝෂ රහිත හඬක් ලබා ගැනීමට කළ යුත්තේ කුමක්ද?", "නියමිත දුර ප්‍රමාණයක් පවත්වා ගනිමින් සෘජුව හා පැහැදිලිව ගැයීම", "මයික්‍රොෆෝනය මුව තුළටම ලං කර කෑගැසීම", "එය අතින් තදින් වසා අල්ලා ගැනීම", "පිටුපස හැරී ඉතා ඈතින් සිට ගැයීම", "නියමිත දුර හා කෝණය රැකීමෙන් 'පොප්' ශබ්ද හා විකෘති වීම් වළකී."),
        q("සංගීතය මානව සෞඛ්‍යය හා මනෝවිද්‍යාව සඳහා යොදාගන්නා නවීන ක්ෂේත්‍රය හඳුන්වන්නේ කුමන නමකින්ද?", "සංගීත චිකිත්සාව (Music Therapy)", "ශබ්ද දූෂණය", "යාන්ත්‍රික ප්‍රතිරෝධය", "දෘශ්‍ය මුද්‍රණ කලාව", "මානසික ආතතිය දුරු කිරීමට හා සුවය සැලසීමට සංගීත චිකිත්සාව ලොව පුරා භාවිත වේ."),
        q("ශ්‍රී ලංකාවේ අධ්‍යාපන පද්ධතිය තුළ සංගීතය සෞන්දර්ය විෂයක් ලෙස ඉගැන්වීමේ ප්‍රධානතම අරමුණ කුමක්ද?", "රසවින්දන හැකියාව, නිර්මාණශීලීත්වය හා සංවේදී පෞරුෂයක් ගොඩනැගීම", "සියලු සිසුන් ව්‍යාපාරිකයන් කිරීම", "ගණිතය හා විද්‍යාව අමතක කරවීම", "තනි භාණ්ඩයක් පමණක් පුහුණු කිරීම", "සමතුලිත මනසක් හා සංස්කෘතික හැඟීමක් ඇති නිර්මාණශීලී පුරවැසියෙකු බිහි කිරීමයි."),
        q("O/L සංගීත ප්‍රායෝගික පරීක්ෂණයේදී රාගයක් ඉදිරිපත් කිරීමේදී අනුගමනය කරන නිවැරදි පිළිවෙළ කුමක්ද?", "ආරෝහණ-අවරෝහණ, පකඩ, බණ්ඩිසයේ ස්ථායි-අන්තරා හා තාන්", "තාන් පමණක් ගයා නැවැත්වීම", "අන්තරාව මුලින් ගයා ආරෝහණය අගට ගැයීම", "තාලය නොසලකා වේගයෙන් වචන කියවීම", "විධිමත් ක්‍රමානුකූල ඉදිරිපත් කිරීම මගින් රාග පිළිබඳ පූර්ණ අවබෝධය ප්‍රදර්ශනය වේ.")
    )
}
